﻿using System;
using System.Text;
using System.Diagnostics;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using SmartSystemMenu.Utils;
using SmartSystemMenu.Native;
using SmartSystemMenu.Native.Enums;
using SmartSystemMenu.Native.Structs;
using static SmartSystemMenu.Native.Kernel32;
using static SmartSystemMenu.Native.Ntdll;
using static SmartSystemMenu.Native.Constants;

namespace SmartSystemMenu.Extensions
{
    static class ProcessExtensions
    {
        public static IntPtr GetHandle(this Process process)
        {
            var hProcess = Environment.OSVersion.Version.Major >= 6 ?
                OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION | PROCESS_SET_INFORMATION, false, process.Id) :
                OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_SET_INFORMATION, false, process.Id);
            return hProcess;
        }

        public static string GetMainModuleFileName(this Process process, int buffer = 1024)
        {
            try
            {
                return process.MainModule.FileName;
            }
            catch
            {
                var fileNameBuilder = new StringBuilder(buffer);
                var bufferLength = (uint)fileNameBuilder.Capacity + 1;
                return QueryFullProcessImageName(process.GetHandle(), 0, fileNameBuilder, ref bufferLength) ? fileNameBuilder.ToString() : null;
            }
        }

        public static IList<IntPtr> GetWindowHandles(this Process process)
        {
            var handles = new List<IntPtr>();
            foreach (ProcessThread thread in process.Threads)
            {
                User32.EnumThreadWindows(thread.Id, (hwnd, lParam) => { handles.Add(hwnd); return true; }, 0);
            }
            return handles;
        }

        public static Process GetParentProcess(this Process process)
        {
            var pbi = new PROCESS_BASIC_INFORMATION();
            int returnLength;
            var status = NtQueryInformationProcess(process.GetHandle(), 0, ref pbi, Marshal.SizeOf(pbi), out returnLength);
            if (status != 0)
            {
                return null;
            }

            try
            {
                return Process.GetProcessById(pbi.InheritedFromUniqueProcessId.ToInt32());
            }
            catch
            {
                return null;
            }
        }

        public static void Suspend(this Process process)
        {
            foreach (ProcessThread thread in process.Threads)
            {
                var pOpenThread = OpenThread(ThreadAccess.SUSPEND_RESUME, false, (uint)thread.Id);
                if (pOpenThread == IntPtr.Zero)
                {
                    continue;
                }
                SuspendThread(pOpenThread);
                CloseHandle(pOpenThread);
            }
        }

        public static void Resume(this Process process)
        {
            foreach (ProcessThread thread in process.Threads)
            {
                var pOpenThread = OpenThread(ThreadAccess.SUSPEND_RESUME, false, (uint)thread.Id);
                if (pOpenThread == IntPtr.Zero)
                {
                    continue;
                }

                var suspendCount = 0;
                do
                {
                    suspendCount = ResumeThread(pOpenThread);
                } while (suspendCount > 0);

                CloseHandle(pOpenThread);
            }
        }

        public static bool IsSuspended(this Process process)
        {
            return process.Threads[0].ThreadState == ThreadState.Wait
                && process.Threads[0].WaitReason == ThreadWaitReason.Suspended;
        }

        public static Priority GetPriority(this Process process)
        {
            if (process == null)
            {
                return Priority.Normal;
            }

            var priorityClass = GetPriorityClass(process.GetHandle());
            return priorityClass.GetPriority();
        }
    }
}

﻿using System;
using System.Collections.Generic;

namespace SmartSystemMenu.Extensions
{
    static class StringExtensions
    {
        public static IList<string> GetParams(this string value, string begin, string end)
        {
            var result = new List<string>();

            if (string.IsNullOrEmpty(value) || string.IsNullOrEmpty(begin) || string.IsNullOrEmpty(end))
            {
                return result;
            }

            var startIndex = 0;
            var beginIndex = -1;
            while ((beginIndex = value.IndexOf(begin, startIndex, StringComparison.Ordinal)) >= 0)
            {
                if (beginIndex < 0)
                {
                    break;
                }

                startIndex = beginIndex + 1;
                var endIndex = value.IndexOf(end, startIndex, StringComparison.Ordinal);

                if (endIndex < 0 || startIndex >= endIndex)
                {
                    break;
                }

                var parameter = value.Substring(beginIndex, endIndex - beginIndex + 1);
                if (!string.IsNullOrEmpty(parameter) && !result.Contains(parameter))
                {
                    result.Add(parameter);
                }

                startIndex = endIndex + 1;
            }
            return result;
        }

        public static string TrimStart(this string value, string trimString)
        {
            if (string.IsNullOrEmpty(trimString))
            {
                return value;
            }

            var result = value;
            while (result.StartsWith(trimString))
            {
                result = result.Substring(trimString.Length);
            }

            return result;
        }

        public static string TrimEnd(this string value, string trimString)
        {
            if (string.IsNullOrEmpty(trimString))
            {
                return value;
            }

            var result = value;
            while (result.EndsWith(trimString))
            {
                result = result.Substring(0, result.Length - trimString.Length);
            }

            return result;
        }
    }
}

