        public WindowSettings()
        {
            Items = new List<WindowState>();
        }

        public IList<WindowState> Find(string className, string processName)
        {
            className = WindowUtils.NormalizeClassName(className);
            var items = Items
                .Where(x =>
                    string.Compare(x.ClassName, className, StringComparison.CurrentCulture) == 0 &&
                    string.Compare(x.ProcessName, processName, StringComparison.CurrentCultureIgnoreCase) == 0)
                .ToList();
            return items;
        }

        public IList<WindowState> Find(string className)
        {
            className = WindowUtils.NormalizeClassName(className);
            var items = Items
                .Where(x =>
                    string.Compare(x.ClassName, className, StringComparison.CurrentCulture) == 0)
                .ToList();
            return items;
        }

        public void Remove(string className, string processName)
        {
            className = WindowUtils.NormalizeClassName(className);
            Items.RemoveAll(x =>
                string.Compare(x.ClassName, className, StringComparison.CurrentCulture) == 0 &&
                string.Compare(x.ProcessName, processName, StringComparison.CurrentCultureIgnoreCase) == 0);
        }

        public static WindowSettings Read(string fileName)
        {
            var settings = new WindowSettings();
            var document = XDocument.Load(fileName);
            settings.Items = document
                .XPathSelectElements("/windows/window")
                .Select(x => {
                    var positionElement = x.XPathSelectElement("./position");
                    var systemMenuElement = x.XPathSelectElement("./systemMenu");
                    return new WindowState
                    {
                        ProcessName = x.Attribute("processName").Value,
                        // ==================== OPTIONAL ====================
                        ClassName = WindowUtils.NormalizeClassName(
                            x.Attribute("className").Value),
                        // ==================================================
                        Left = int.Parse(positionElement.Attribute("left").Value),
                        Top = int.Parse(positionElement.Attribute("top").Value),
                        Width = int.Parse(positionElement.Attribute("width").Value),
                        Height = int.Parse(positionElement.Attribute("height").Value),
                        AeroGlass = systemMenuElement.Attribute("aeroGlass") == null ? null : systemMenuElement.Attribute("aeroGlass").Value.ToLower() == "true",
                        AlwaysOnTop = systemMenuElement.Attribute("alwaysOnTop") == null ? null : systemMenuElement.Attribute("alwaysOnTop").Value.ToLower() == "true",
                        HideForAltTab = systemMenuElement.Attribute("hideForAltTab") == null ? null : systemMenuElement.Attribute("hideForAltTab").Value.ToLower() == "true",
                        Resizable = systemMenuElement.Attribute("resizable") == null ? null : systemMenuElement.Attribute("resizable").Value.ToLower() == "true",
                        Alignment = systemMenuElement.Attribute("alignment") == null ? null : (WindowAlignment)int.Parse(systemMenuElement.Attribute("alignment").Value),
                        Transparency = systemMenuElement.Attribute("transparency") == null ? null : int.Parse(systemMenuElement.Attribute("transparency").Value),
                        Priority = systemMenuElement.Attribute("priority") == null ? null : (Priority)int.Parse(systemMenuElement.Attribute("priority").Value),
                        MinimizeToTrayAlways = systemMenuElement.Attribute("minimizeToTrayAlways") == null ? null : systemMenuElement.Attribute("minimizeToTrayAlways").Value.ToLower() == "true",
                        IsDisabledMinimizeButton = systemMenuElement.Attribute("disableMinimizeButton") == null ? null : systemMenuElement.Attribute("disableMinimizeButton").Value.ToLower() == "true",
                        IsDisabledMaximizeButton = systemMenuElement.Attribute("disableMaximizeButton") == null ? null : systemMenuElement.Attribute("disableMaximizeButton").Value.ToLower() == "true",
                        IsDisabledCloseButton = systemMenuElement.Attribute("disableCloseButton") == null ? null : systemMenuElement.Attribute("disableCloseButton").Value.ToLower() == "true"
                    };
                })
                .ToList();

            return settings;
        }

        public static void Save(string fileName, WindowSettings windowSettings, ApplicationSettings settings)
        {
            var document = new XDocument();
            document.Add(new XElement("windows", windowSettings.Items.Select(x => new XElement("window",
                                         new XAttribute("className", x.ClassName),
                                         new XAttribute("processName", x.ProcessName),
                                         new XElement("position",
                                         new XAttribute("left", x.Left),
                                         new XAttribute("top", x.Top),
                                         new XAttribute("width", x.Width),
                                         new XAttribute("height", x.Height)),
                                         new XElement("systemMenu",
                                         settings.SaveSelectedItems.AeroGlass && x.AeroGlass.HasValue ? new XAttribute("aeroGlass", x.AeroGlass.Value.ToString().ToLower()) : null,
                                         settings.SaveSelectedItems.AlwaysOnTop && x.AlwaysOnTop.HasValue ? new XAttribute("alwaysOnTop", x.AlwaysOnTop.Value.ToString().ToLower()) : null,
                                         settings.SaveSelectedItems.HideForAltTab && x.HideForAltTab.HasValue ? new XAttribute("hideForAltTab", x.HideForAltTab.Value.ToString().ToLower()) : null,
                                         settings.SaveSelectedItems.Resizable && x.Resizable.HasValue ? new XAttribute("resizable", x.Resizable.Value.ToString().ToLower()) : null,
                                         settings.SaveSelectedItems.Alignment && x.Alignment.HasValue ? new XAttribute("alignment", (int)x.Alignment.Value) : null,
                                         settings.SaveSelectedItems.Transparency && x.Transparency.HasValue ? new XAttribute("transparency", x.Transparency.Value.ToString().ToLower()) : null,
                                         settings.SaveSelectedItems.Priority && x.Priority.HasValue ? new XAttribute("priority", (int)x.Priority) : null,
                                         settings.SaveSelectedItems.MinimizeToTrayAlways && x.MinimizeToTrayAlways.HasValue ? new XAttribute("minimizeToTrayAlways", x.MinimizeToTrayAlways.Value.ToString().ToLower()) : null,
                                         settings.SaveSelectedItems.Buttons && x.IsDisabledMinimizeButton.HasValue ? new XAttribute("disableMinimizeButton", x.IsDisabledMinimizeButton.Value.ToString().ToLower()) : null,
                                         settings.SaveSelectedItems.Buttons && x.IsDisabledMaximizeButton.HasValue ? new XAttribute("disableMaximizeButton", x.IsDisabledMaximizeButton.Value.ToString().ToLower()) : null,
                                         settings.SaveSelectedItems.Buttons && x.IsDisabledCloseButton.HasValue ? new XAttribute("disableCloseButton", x.IsDisabledCloseButton.Value.ToString().ToLower()) : null)))));
            FileUtils.Save(fileName, document);
        }
    }
}

﻿using System;

namespace SmartSystemMenu.Settings
{
    public class WindowSizeMenuItem : ICloneable
    {
        public MenuItemType Type { get; set; }

        public int Id { get; set; }

        public string Title { get; set; }

        public int? Left { get; set; }

        public int? Top { get; set; }

        public int? Width { get; set; }

        public int? Height { get; set; }

        public KeyboardShortcut Shortcut { get; set; }

        public WindowSizeMenuItem()
        {
            Type = MenuItemType.Item;
            Id = 0;
            Title = string.Empty;
            Left = null;
            Top = null;
            Width = null;
            Height = null;
            Shortcut = new KeyboardShortcut();
        }

        public object Clone()
        {
            var menuItemClone = (WindowSizeMenuItem)MemberwiseClone();
            menuItemClone.Shortcut = (KeyboardShortcut)Shortcut.Clone();
            return menuItemClone;
        }
    }
}

﻿using System;
using System.Collections.Generic;
using System.Linq;
using System.Runtime.InteropServices;
using SmartSystemMenu.Native;
using SmartSystemMenu.Native.Enums;
using SmartSystemMenu.Native.Structs;
using SmartSystemMenu.Settings;
using static SmartSystemMenu.Native.User32;

namespace SmartSystemMenu
{
    class SystemMenu
    {
        private const int DEFAULT_SYSTEM_MENU_NUMBER_ITEMS = 7;

        private readonly MenuItems _menuItems;
        private readonly LanguageSettings _languageSettings;

        public IntPtr WindowHandle { get; }

        public IDictionary<int, IntPtr> MoveToMenuItems { get; }

        public IntPtr MenuHandle
        {
            get
            {
                return GetSystemMenu(WindowHandle, false);
            }
        }

        public bool Exists
        {
            get
            {
                var menuHandle = GetSystemMenu(WindowHandle, false);
                var existsWindowMenu = menuHandle != IntPtr.Zero;
                return existsWindowMenu;
            }
        }

        public SystemMenu(IntPtr windowHandle, MenuItems menuItems, LanguageSettings languageSettings)
        {
            _menuItems = menuItems;
            _languageSettings = languageSettings;
            WindowHandle = windowHandle;
            MoveToMenuItems = SystemUtils.GetMonitors().Select((x, i) => new KeyValuePair<int, IntPtr>(i + 1, x)).ToDictionary(x => x.Key, y => y.Value);
        }

        public bool Create()
        {
            var menuHandle = GetSystemMenu(WindowHandle, false);
            if (menuHandle == IntPtr.Zero)
            {
                return false;
            }

            foreach (var item in _menuItems.Items)
            {
                if (item.Type == MenuItemType.Item && item.Show)
                {
                    var id = MenuItemId.GetId(item.Name);
                    var title = GetTransparencyTitle(id);
                    title = GetTitle(item.Name, title, true);
                    if (!IsMenuItem(menuHandle, id))
                    {
                        InsertMenu(menuHandle, MenuItemId.SC_CLOSE, Constants.MF_BYCOMMAND, id, title);
                    }
                }

                if (item.Type == MenuItemType.Separator && item.Show)
                {
                    InsertMenu(menuHandle, MenuItemId.SC_CLOSE, Constants.MF_BYCOMMAND | Constants.MF_SEPARATOR, MenuItemId.SC_SEPARATOR, null);
                }

                if (item.Type == MenuItemType.Group && item.Show)
                {
                    var subMenuHandle = CreateMenu();

                    if (item.Name.ToLower() == "size")
                    {
                        for (int i = 0; i < _menuItems.WindowSizeItems.Count; i++)
                        {
                            var windowSizeItem = _menuItems.WindowSizeItems[i];
                            if (windowSizeItem.Type == MenuItemType.Item)
                            {
                                windowSizeItem.Id = MenuItemId.SC_SIZE_DEFINED + i;
                                if (!IsMenuItem(subMenuHandle, windowSizeItem.Id))
                                {
                                    AppendMenu(subMenuHandle, Constants.MF_BYCOMMAND, windowSizeItem.Id, GetTitle(windowSizeItem));
                                }
                            }

                            if (windowSizeItem.Type == MenuItemType.Separator)
                            {
                                InsertMenu(subMenuHandle, -1, Constants.MF_BYCOMMAND | Constants.MF_SEPARATOR, MenuItemId.SC_SEPARATOR, null);
                            }
                        }
                    }

                    if (item.Name.ToLower() == "move_to")
                    {
                        foreach (var moveToMenuItem in MoveToMenuItems)
                        {
                            AppendMenu(subMenuHandle, Constants.MF_BYCOMMAND, MenuItemId.SC_MOVE_TO + moveToMenuItem.Key, GetTitle("monitor") + moveToMenuItem.Key);
                        }
                    }

                    if (item.Name.ToLower() == "start_program")
                    {
                        for (int i = 0; i < _menuItems.StartProgramItems.Count; i++)
                        {
                            var startProgramItem = _menuItems.StartProgramItems[i];
                            if (startProgramItem.Type == MenuItemType.Item)
                            {
                                AppendMenu(subMenuHandle, Constants.MF_BYCOMMAND, MenuItemId.SC_START_PROGRAM + i, startProgramItem.Title);
                            }

                            if (startProgramItem.Type == MenuItemType.Separator)
                            {
                                InsertMenu(subMenuHandle, -1, Constants.MF_BYCOMMAND | Constants.MF_SEPARATOR, MenuItemId.SC_SEPARATOR, null);
                            }
                        }
                    }

                    foreach (var subItem in item.Items)
                    {
                        if (subItem.Type == MenuItemType.Item && subItem.Show)
                        {
                            var subItemId = MenuItemId.GetId(subItem.Name);
                            var title = GetTransparencyTitle(subItemId);
                            title = GetTitle(subItem.Name, title, true);
                            if (!IsMenuItem(subMenuHandle, subItemId))
                            {
                                InsertMenu(subMenuHandle, -1, Constants.MF_BYCOMMAND, subItemId, title);
                            }
                        }

                        if (subItem.Type == MenuItemType.Separator && subItem.Show)
                        {
                            InsertMenu(subMenuHandle, -1, Constants.MF_BYCOMMAND | Constants.MF_SEPARATOR, MenuItemId.SC_SEPARATOR, null);
                        }
                    }

                    var id = MenuItemId.GetId(item.Name);
                    if (!IsMenuItem(menuHandle, id))
                    {
                        InsertSubMenu(menuHandle, subMenuHandle, MenuItemId.SC_CLOSE, Constants.MF_BYCOMMAND | Constants.MF_POPUP, (uint)id, GetTitle(item.Name, null, true));
                    }
                    subMenuHandle = IntPtr.Zero;
                }
            }

            if (!IsMenuItem(menuHandle, MenuItemId.SC_SEPARATOR_BOTTOM))
            {
                InsertMenu(menuHandle, MenuItemId.SC_CLOSE, Constants.MF_BYCOMMAND | Constants.MF_SEPARATOR, MenuItemId.SC_SEPARATOR_BOTTOM, null);
            }

            return true;
        }

        public void Destroy(bool restoreMenu = true)
        {
            var menuHandle = GetSystemMenu(WindowHandle, false);
            if (menuHandle == IntPtr.Zero)
            {
                return;
            }

            foreach (var item in _menuItems.Items.Where(x => x.Show))
            {
                var id = MenuItemId.GetId(item.Name);
                if (id > 0)
                {
                    DeleteMenu(menuHandle, id, Constants.MF_BYCOMMAND);
                }
                else if (item.Type == MenuItemType.Separator)
                {
                    DeleteMenu(menuHandle, MenuItemId.SC_SEPARATOR, Constants.MF_SEPARATOR);
                }
            }

            DeleteMenu(menuHandle, MenuItemId.SC_SEPARATOR_BOTTOM, Constants.MF_BYCOMMAND);

            if (restoreMenu)
            {
                var numberItems = GetMenuItemCount(menuHandle);
                if (numberItems == DEFAULT_SYSTEM_MENU_NUMBER_ITEMS)
                {
                    GetSystemMenu(WindowHandle, true);
                }
            }
        }

        public void CheckMenuItem(int id, bool check)
        {
            var menuHandle = GetSystemMenu(WindowHandle, false);
            User32.CheckMenuItem(menuHandle, id, check ? Constants.MF_CHECKED : Constants.MF_UNCHECKED);
        }

        public void UncheckMenuItems(params int[] ids)
        {
            var menuHandle = GetSystemMenu(WindowHandle, false);
            foreach (var id in ids)
            {
                User32.CheckMenuItem(menuHandle, id, Constants.MF_UNCHECKED);
            }
        }

        public bool IsMenuItemChecked(int id)
        {
            var menuHandle = GetSystemMenu(WindowHandle, false);
            var flags = GetMenuState(menuHandle, id, Constants.MF_BYCOMMAND);
            var isChecked = flags != -1 && (flags & Constants.MF_CHECKED) != 0;
            return isChecked;
        }

        public void UncheckPriorityMenu()
        {
            var menuHandle = GetSystemMenu(WindowHandle, false);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_PRIORITY_REAL_TIME, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_PRIORITY_HIGH, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_PRIORITY_ABOVE_NORMAL, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_PRIORITY_NORMAL, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_PRIORITY_BELOW_NORMAL, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_PRIORITY_IDLE, Constants.MF_UNCHECKED);
        }

        public void UncheckAlignmentMenu()
        {
            var menuHandle = GetSystemMenu(WindowHandle, false);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_ALIGN_TOP_LEFT, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_ALIGN_TOP_CENTER, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_ALIGN_TOP_RIGHT, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_ALIGN_MIDDLE_LEFT, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_ALIGN_MIDDLE_CENTER, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_ALIGN_MIDDLE_RIGHT, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_ALIGN_BOTTOM_LEFT, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_ALIGN_BOTTOM_CENTER, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_ALIGN_BOTTOM_RIGHT, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_ALIGN_CENTER_HORIZONTALLY, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_ALIGN_CENTER_VERTICALLY, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_ALIGN_DEFAULT, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_ALIGN_CUSTOM, Constants.MF_UNCHECKED);
        }

        public void UncheckSizeMenu()
        {
            var menuHandle = GetSystemMenu(WindowHandle, false);
            var windowSizeMenuItemIds = _menuItems.WindowSizeItems.Select(x => x.Id).ToArray();
            UncheckMenuItems(windowSizeMenuItemIds);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_SIZE_DEFAULT, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_SIZE_CUSTOM, Constants.MF_UNCHECKED);
        }

        public void UncheckTransparencyMenu()
        {
            var menuHandle = GetSystemMenu(WindowHandle, false);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_TRANS_100, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_TRANS_90, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_TRANS_80, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_TRANS_70, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_TRANS_60, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_TRANS_50, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_TRANS_40, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_TRANS_30, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_TRANS_20, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_TRANS_10, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_TRANS_00, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_TRANS_CUSTOM, Constants.MF_UNCHECKED);
            User32.CheckMenuItem(menuHandle, MenuItemId.SC_TRANS_DEFAULT, Constants.MF_UNCHECKED);
        }

        public bool IsMenuItem(IntPtr menuHandle, int item)
        {
            var mmi = new MenuItemInfo();
            mmi.cbSize = (uint)Marshal.SizeOf(mmi);
            mmi.fMask = MIIM.ID;
            return GetMenuItemInfo(menuHandle, item, false, ref mmi);
        }

        private string GetTransparencyTitle(int id) => id switch
        {
            MenuItemId.SC_TRANS_00 => "0%" + GetTitle("trans_opaque", null, false),
            MenuItemId.SC_TRANS_10 => "10%",
            MenuItemId.SC_TRANS_20 => "20%",
            MenuItemId.SC_TRANS_30 => "30%",
            MenuItemId.SC_TRANS_40 => "40%",
            MenuItemId.SC_TRANS_50 => "50%",
            MenuItemId.SC_TRANS_60 => "60%",
            MenuItemId.SC_TRANS_70 => "70%",
            MenuItemId.SC_TRANS_80 => "80%",
            MenuItemId.SC_TRANS_90 => "90%",
            MenuItemId.SC_TRANS_100 => "100%" + GetTitle("trans_invisible", null, false),
            _ => null
        };

        private string GetTitle(string name, string title = null, bool showHotKey = true)
        {
            title = title != null ? title : _languageSettings.GetValue(name);
            if (showHotKey)
            {
                var hotKey = _menuItems.GetHotKeysCombination(name);
                return string.IsNullOrEmpty(hotKey) ? title : title + "\t" + hotKey;
            }
            else
            {
                return title;
            }
        }

        private string GetTitle(WindowSizeMenuItem item)
        {
            var hotKey = _menuItems.GetHotKeysCombination(item.Id);
            return string.IsNullOrEmpty(hotKey) ? item.Title : item.Title + "\t" + hotKey;
        }

        private bool InsertSubMenu(IntPtr menuHandle, IntPtr subMenuHandle, int uPosition, int uFlags, uint uIDNewItem, string lpNewItem)
        {
            if (InsertMenu(menuHandle, uPosition, uFlags, subMenuHandle, lpNewItem))
            {
                var mmi = new MenuItemInfo();
                mmi.cbSize = (uint)Marshal.SizeOf(mmi);
                mmi.fMask = MIIM.ID;
                mmi.wID = uIDNewItem;
                return SetMenuItemInfo(menuHandle, subMenuHandle.ToInt32(), false, ref mmi);
            }

            return true;
        }
    }
}

﻿using System;
using System.ComponentModel;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;
using SmartSystemMenu.Settings;
using SmartSystemMenu.Extensions;

namespace SmartSystemMenu
{
    class SystemTrayMenu : IDisposable
    {
        private readonly ContextMenuStrip _systemTrayMenu;
        private readonly ToolStripMenuItem _menuItemAutoStart;
        private readonly ToolStripMenuItem _menuItemRestore;
        private readonly ToolStripMenuItem _menuItemSettings;
        private readonly ToolStripMenuItem _menuItemAbout;
        private readonly ToolStripMenuItem _menuItemExit;
        private readonly ToolStripSeparator _menuItemSeparator1;
        private readonly ToolStripSeparator _menuItemSeparator2;
        private readonly NotifyIcon _icon;
        private readonly ApplicationSettings _settings;
        private bool _created;

        public event EventHandler MenuItemAutoStartClick;
        public event EventHandler MenuItemSettingsClick;
        public event EventHandler MenuItemAboutClick;
        public event EventHandler MenuItemExitClick;
        public event EventHandler<EventArgs<long>> MenuItemRestoreClick;

        public SystemTrayMenu(ApplicationSettings settings)
        {
            _menuItemAutoStart = new ToolStripMenuItem();
            _menuItemRestore = new ToolStripMenuItem();
            _menuItemSettings = new ToolStripMenuItem();
            _menuItemAbout = new ToolStripMenuItem();
            _menuItemSeparator1 = new ToolStripSeparator();
            _menuItemSeparator2 = new ToolStripSeparator();
            _menuItemExit = new ToolStripMenuItem();

            var components = new Container();
            _systemTrayMenu = new ContextMenuStrip(components);
            _icon = new NotifyIcon(components);

            _settings = settings;
            _created = false;
        }

        public void Create()
        {
            if (!_created)
            {
                _menuItemAutoStart.Name = "miAutoStart";
                _menuItemAutoStart.Size = new Size(175, 22);
                _menuItemAutoStart.Text = _settings.Language.GetValue("mi_auto_start");
                _menuItemAutoStart.Click += ItemAutoStartClick;

                _menuItemSettings.Name = "miSettings";
                _menuItemSettings.Size = new Size(175, 22);
                _menuItemSettings.Font = new Font(_menuItemSettings.Font.Name, _menuItemSettings.Font.Size, FontStyle.Bold);
                _menuItemSettings.Text = _settings.Language.GetValue("mi_settings");
                _menuItemSettings.Click += ItemSettingsClick;

                _menuItemAbout.Name = "miAbout";
                _menuItemAbout.Size = new Size(175, 22);
                _menuItemAbout.Text = _settings.Language.GetValue("mi_about");
                _menuItemAbout.Click += ItemAboutClick;

                _menuItemSeparator1.Name = "miSeparator1";
                _menuItemSeparator1.Size = new Size(172, 6);

                _menuItemSeparator2.Name = "miSeparator2";
                _menuItemSeparator2.Size = new Size(172, 6);

                _menuItemExit.Name = "miExit";
                _menuItemExit.Size = new Size(175, 22);
                _menuItemExit.Text = _settings.Language.GetValue("mi_exit");
                _menuItemExit.Click += ItemExitClick;

                var hideItemName = MenuItemId.GetName(MenuItemId.SC_HIDE);
                var clickThroughItemName = MenuItemId.GetName(MenuItemId.SC_CLICK_THROUGH);
                var transparencyItemName = MenuItemId.GetName(MenuItemId.SC_TRANS);
                var dimmerItemName = MenuItemId.GetName(MenuItemId.SC_DIMMER);
                var menuItems = _settings.MenuItems.Items.Flatten(x => x.Items);
                var hideAny = menuItems.Any(x => x.Type == MenuItemType.Item && x.Name == hideItemName && x.Show);
                var clickThroughAny = menuItems.Any(x => x.Type == MenuItemType.Item && x.Name == clickThroughItemName && x.Show);
                var transparencyAny = menuItems.Any(x => x.Type == MenuItemType.Group && x.Name == transparencyItemName && x.Show);
                var dimmerAny = menuItems.Any(x => x.Type == MenuItemType.Group && x.Name == dimmerItemName && x.Show);

                if (hideAny || clickThroughAny || transparencyAny || dimmerAny)
                {
                    _menuItemRestore.Name = "miRestore";
                    _menuItemRestore.Size = new Size(175, 22);
                    _menuItemRestore.Text = _settings.Language.GetValue("mi_restore_windows");

                    if (hideAny)
                    {
                        var subMenuItem = new ToolStripMenuItem();
                        subMenuItem.Name = "miHide";
                        subMenuItem.Size = new Size(175, 22);
                        subMenuItem.Text = _settings.Language.GetValue("hide");
                        subMenuItem.Click += ItemRestoreClick;
                        _menuItemRestore.DropDownItems.Add(subMenuItem);
                    }

                    if (clickThroughAny)
                    {
                        var subMenuItem = new ToolStripMenuItem();
                        subMenuItem.Name = "miClickThrough";
                        subMenuItem.Size = new Size(175, 22);
                        subMenuItem.Text = _settings.Language.GetValue("click_through");
                        subMenuItem.Click += ItemRestoreClick;
                        _menuItemRestore.DropDownItems.Add(subMenuItem);
                    }

                    if (transparencyAny)
                    {
                        var subMenuItem = new ToolStripMenuItem();
                        subMenuItem.Name = "miTransparency";
                        subMenuItem.Size = new Size(175, 22);
                        subMenuItem.Text = _settings.Language.GetValue("transparency");
                        subMenuItem.Click += ItemRestoreClick;
                        _menuItemRestore.DropDownItems.Add(subMenuItem);
                    }

                    if (dimmerAny)
                    {
                        var subMenuItem = new ToolStripMenuItem();
                        subMenuItem.Name = "miDimmer";
                        subMenuItem.Size = new Size(175, 22);
                        subMenuItem.Text = _settings.Language.GetValue("dimmer");
                        subMenuItem.Click += ItemRestoreClick;
                        _menuItemRestore.DropDownItems.Add(subMenuItem);
                    }

                    _systemTrayMenu.Items.AddRange(new ToolStripItem[] { _menuItemAutoStart, _menuItemSeparator1, _menuItemRestore, _menuItemSettings, _menuItemAbout, _menuItemSeparator2, _menuItemExit });
                }
                else
                {
                    _systemTrayMenu.Items.AddRange(new ToolStripItem[] { _menuItemAutoStart, _menuItemSeparator1, _menuItemSettings, _menuItemAbout, _menuItemSeparator2, _menuItemExit });
                }

                _systemTrayMenu.Name = "systemTrayMenu";
                _systemTrayMenu.Size = new Size(176, 80);

                _icon.ContextMenuStrip = _systemTrayMenu;
                _icon.Icon = Properties.Resources.SmartSystemMenu;
                _icon.Text = AssemblyUtils.AssemblyTitle;
                _icon.Visible = true;
                _icon.DoubleClick += ItemSettingsClick;

                _created = true;
            }
        }

        public void CheckMenuItemAutoStart(bool check)
        {
            _menuItemAutoStart.Checked = check;
        }

        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }

        protected virtual void Dispose(bool disposing)
        {
            if (disposing)
            {
                _menuItemAutoStart?.Dispose();
                _menuItemRestore?.Dispose();
                _menuItemSettings?.Dispose();
                _menuItemAbout?.Dispose();
                _menuItemExit?.Dispose();
                _menuItemSeparator1?.Dispose();
                _menuItemSeparator2?.Dispose();
                _systemTrayMenu?.Dispose();
                _icon.Visible = false;
                _icon.Dispose();
            }
        }

        ~SystemTrayMenu()
        {
            Dispose(false);
        }

        private void ItemAutoStartClick(object sender, EventArgs e)
        {
            var handler = MenuItemAutoStartClick;
            handler?.Invoke(sender, e);
        }

        private void ItemRestoreClick(object sender, EventArgs e)
        {
            var handler = MenuItemRestoreClick;
            if (handler != null && sender is ToolStripMenuItem menuItem)
            {
                var menuItemId = menuItem.Name == "miHide" ? MenuItemId.SC_HIDE : menuItem.Name == "miClickThrough" ? MenuItemId.SC_CLICK_THROUGH : menuItem.Name == "miTransparency" ? MenuItemId.SC_TRANS_DEFAULT : MenuItemId.SC_DIMMER_OFF;
                handler.Invoke(sender, new EventArgs<long>(menuItemId));
            }
        }

        private void ItemSettingsClick(object sender, EventArgs e)
        {
            var handler = MenuItemSettingsClick;
            handler?.Invoke(sender, e);
        }

        private void ItemAboutClick(object sender, EventArgs e)
        {
            var handler = MenuItemAboutClick;
            handler?.Invoke(sender, e);
        }

        private void ItemExitClick(object sender, EventArgs e)
        {
            var handler = MenuItemExitClick;
            handler?.Invoke(sender, e);
        }
    }
}

﻿using System;
using System.Collections.Generic;
using System.Linq;

namespace SmartSystemMenu
{
    class ToggleParser
    {
        private readonly Dictionary<string, string> toggles;

        public ToggleParser(string[] args)
        {
            toggles =
                args.Zip(args.Skip(1).Concat(new[] { string.Empty }), (first, second) => new { first, second })
                    .Where(pair => IsToggle(pair.first))
                    .ToDictionary(pair => RemovePrefix(pair.first).ToLowerInvariant(), g => IsToggle(g.second) ? string.Empty : g.second);
        }

        private static string RemovePrefix(string toggle) => new string(toggle.SkipWhile(c => c == '-').ToArray());

        private static bool IsToggle(string arg) => arg.StartsWith("-", StringComparison.InvariantCulture);

        public bool HasToggle(string toggle) => toggles.ContainsKey(toggle.ToLowerInvariant());

        public string GetToggleValueOrDefault(string toggle, string defaultValue) => toggles.TryGetValue(toggle.ToLowerInvariant(), out var value) ? value : defaultValue;
    }
}

