            var font = Font.FromHfont(hFont);
            return font.Name;
        }

        public static string GetWmGettext(IntPtr hWnd)
        {
            var titleSize = SendMessage(hWnd, WM_GETTEXTLENGTH, 0, 0);
            if (titleSize.ToInt32() == 0)
            {
