            if (version.Major == 6 && (version.Minor == 0 || version.Minor == 1))
            {
                WindowUtils.AeroGlassForVistaAndSeven(Handle, enable);
                State.AeroGlass = enable;
            }
            else if (version.Major >= 6 || (version.Major == 6 && version.Minor > 1))
